INSERT INTO `product` VALUES (1, 'master_service', 'MS_BAZI', '八字精批', '详解命盘格局，分析一生运势', '资深命理师亲自批断，包含：命盘格局分析、五行喜忌、大运流年、事业财运、婚姻感情、健康运势等全方位解读。', '📊', '', NULL, 199.00, 399.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, 'hot', '', 0, '{\"format\": \"图文报告+语音解读\", \"delivery\": \"24小时内\"}', 1, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
INSERT INTO `product` VALUES (2, 'master_service', 'MS_HEHUN', '姻缘合婚', '双方八字合盘，婚姻吉凶预测', '分析双方八字契合度，包含：五行互补、生肖配对、日柱合婚、婚姻宫位、子女缘分等深度解析。', '💑', '', NULL, 299.00, 599.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, '', '', 0, '{\"format\": \"图文报告\", \"delivery\": \"48小时内\"}', 2, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
INSERT INTO `product` VALUES (3, 'master_service', 'MS_LIUNIAN', '流年运势', '2026年运势详批，把握关键时机', '详批来年运势走向，包含：整体运势、每月运程、事业机遇、财运起伏、感情变化、注意事项。', '📅', '', NULL, 99.00, 199.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, 'new', '', 0, '{\"format\": \"图文报告\", \"delivery\": \"12小时内\"}', 3, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
INSERT INTO `product` VALUES (4, 'master_service', 'MS_CAIYUN', '事业财运', '事业方向指引，财运旺衰分析', '专项分析事业财运，包含：适合行业、发展方向、贵人方位、求财时机、投资建议。', '💰', '', NULL, 168.00, 336.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, '', '', 0, '{\"format\": \"图文报告\", \"delivery\": \"24小时内\"}', 4, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
INSERT INTO `product` VALUES (5, 'master_service', 'MS_QIMING', '宝宝起名', '结合八字五行，起个好名字', '根据宝宝生辰八字，结合五行喜用、音韵美感、寓意内涵，提供3-5个精选名字方案。', '👶', '', NULL, 299.00, 599.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, 'recommend', '', 0, '{\"format\": \"起名报告+备选方案\", \"delivery\": \"48小时内\"}', 5, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
INSERT INTO `product` VALUES (6, 'master_service', 'MS_ZEJI', '择吉选日', '婚嫁开业，选个好日子', '根据当事人八字，结合黄历吉凶，为婚嫁、开业、搬家、动土等重要事项选择吉日良辰。', '📆', '', NULL, 88.00, 168.00, 0.00, 'CNY', -1, 0, 0, 0, NULL, NULL, '', '', 0, '{\"format\": \"吉日报告\", \"delivery\": \"12小时内\"}', 6, 0, 1, '', '', '2026-01-12 20:34:08', '2026-01-12 20:34:08');
