-- 创建数据库
CREATE DATABASE IF NOT EXISTS starloom DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE starloom;

-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
                            `id` bigint(20) NOT NULL AUTO_INCREMENT,
                            `category_id` bigint(20) NULL DEFAULT 0 COMMENT '分类ID',
                            `category_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分类名称(冗余)',
                            `parent_category_id` bigint(20) NULL DEFAULT 0 COMMENT '父分类ID(冗余)',
                            `parent_category_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '父分类名称(冗余)',
                            `full_category` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '完整分类路径(冗余)',
                            `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章标题',
                            `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章摘要',
                            `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章内容(纯文本)',
                            `content_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始HTML内容',
                            `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '作者',
                            `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '标签(冗余)，逗号分隔',
                            `source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '来源网站名称',
                            `source_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原文链接',
                            `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封面图片',
                            `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章图片列表(JSON)',
                            `word_count` int(11) NULL DEFAULT 0 COMMENT '字数',
                            `publish_time` datetime NULL DEFAULT NULL COMMENT '原文发布时间',
                            `view_count` int(11) NULL DEFAULT 0 COMMENT '浏览量',
                            `like_count` int(11) NULL DEFAULT 0 COMMENT '点赞数',
                            `collect_count` int(11) NULL DEFAULT 0 COMMENT '收藏数',
                            `comment_count` int(11) NULL DEFAULT 0 COMMENT '评论数',
                            `is_top` tinyint(4) NULL DEFAULT 0 COMMENT '是否置顶: 0-否 1-是',
                            `is_recommend` tinyint(4) NULL DEFAULT 0 COMMENT '是否推荐: 0-否 1-是',
                            `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-草稿 1-已发布 2-已删除',
                            `crawl_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '爬取时间',
                            `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建人',
                            `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '修改人',
                            `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                            `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
                            PRIMARY KEY (`id`) USING BTREE,
                            UNIQUE INDEX `uk_source_url`(`source_url`) USING BTREE,
                            INDEX `idx_category_id`(`category_id`) USING BTREE,
                            INDEX `idx_parent_category_id`(`parent_category_id`) USING BTREE,
                            INDEX `idx_publish_time`(`publish_time`) USING BTREE,
                            INDEX `idx_status`(`status`) USING BTREE,
                            INDEX `idx_is_top`(`is_top`) USING BTREE,
                            INDEX `idx_is_recommend`(`is_recommend`) USING BTREE,
                            INDEX `idx_created_at`(`created_at`) USING BTREE,
                            FULLTEXT INDEX `ft_title_content`(`title`, `content`) WITH PARSER `ngram`
) ENGINE = InnoDB AUTO_INCREMENT = 762 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '爬取文章' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article
-- ----------------------------

-- ----------------------------
-- Table structure for category
-- ----------------------------
DROP TABLE IF EXISTS `category`;
CREATE TABLE `category`  (
                             `id` bigint(20) NOT NULL AUTO_INCREMENT,
                             `parent_id` bigint(20) NULL DEFAULT 0 COMMENT '父分类ID，0表示顶级分类',
                             `parent_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '父分类名称(冗余)',
                             `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
                             `full_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '完整分类路径，如: 基础/术语',
                             `slug` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类标识/URL路径',
                             `icon` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分类图标',
                             `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分类描述',
                             `level` tinyint(4) NULL DEFAULT 1 COMMENT '层级: 1-大分类 2-小分类',
                             `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                             `article_count` int(11) NULL DEFAULT 0 COMMENT '文章数量(冗余)',
                             `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-禁用 1-启用',
                             `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建人',
                             `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '修改人',
                             `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                             `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
                             PRIMARY KEY (`id`) USING BTREE,
                             UNIQUE INDEX `uk_slug`(`slug`) USING BTREE,
                             INDEX `idx_parent_id`(`parent_id`) USING BTREE,
                             INDEX `idx_level`(`level`) USING BTREE,
                             INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of category
-- ----------------------------

-- ----------------------------
-- Table structure for daily_stats
-- ----------------------------
DROP TABLE IF EXISTS `daily_stats`;
CREATE TABLE `daily_stats`  (
                                `stats_date` date NOT NULL COMMENT '统计日期',
                                `page_views` int(11) NULL DEFAULT 0 COMMENT '页面访问量',
                                `unique_visitors` int(11) NULL DEFAULT 0 COMMENT '独立访客数',
                                `new_users` int(11) NULL DEFAULT 0 COMMENT '新用户数',
                                `bounce_rate` int(11) NULL DEFAULT 0 COMMENT '跳出率(%)',
                                `total_users` int(11) NULL DEFAULT 0 COMMENT '总用户数',
                                `active_users` int(11) NULL DEFAULT 0 COMMENT '活跃用户数',
                                `vip_users` int(11) NULL DEFAULT 0 COMMENT 'VIP用户数',
                                `new_vip_users` int(11) NULL DEFAULT 0 COMMENT '新VIP用户数',
                                `total_orders` int(11) NULL DEFAULT 0 COMMENT '总订单数',
                                `paid_orders` int(11) NULL DEFAULT 0 COMMENT '已支付订单数',
                                `cancelled_orders` int(11) NULL DEFAULT 0 COMMENT '取消订单数',
                                `total_revenue` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '总收入',
                                `vip_revenue` decimal(10, 2) NULL DEFAULT 0.00 COMMENT 'VIP收入',
                                `avg_online_time` int(11) NULL DEFAULT 0 COMMENT '平均在线时长(分钟)',
                                `peak_online_count` int(11) NULL DEFAULT 0 COMMENT '峰值在线人数',
                                `error_count` int(11) NULL DEFAULT 0 COMMENT '错误次数',
                                `api_calls` int(11) NULL DEFAULT 0 COMMENT 'API调用次数',
                                `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                PRIMARY KEY (`stats_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of daily_stats
-- ----------------------------

-- ----------------------------
-- Table structure for event_log
-- ----------------------------
DROP TABLE IF EXISTS `event_log`;
CREATE TABLE `event_log`  (
                              `id` bigint(20) NOT NULL AUTO_INCREMENT,
                              `event_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型: pv/tool_use',
                              `tool_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工具ID',
                              `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会话ID',
                              `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
                              `device_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型',
                              `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
                              PRIMARY KEY (`id`) USING BTREE,
                              INDEX `idx_created_at`(`created_at`) USING BTREE,
                              INDEX `idx_tool_id`(`tool_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 148 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '事件日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of event_log
-- ----------------------------

-- ----------------------------
-- Table structure for online_session
-- ----------------------------
DROP TABLE IF EXISTS `online_session`;
CREATE TABLE `online_session`  (
                                   `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
                                   `last_active` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                   PRIMARY KEY (`session_id`) USING BTREE,
                                   INDEX `idx_last_active`(`last_active`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '在线会话表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of online_session
-- ----------------------------

-- ----------------------------
-- Table structure for page_view
-- ----------------------------
DROP TABLE IF EXISTS `page_view`;
CREATE TABLE `page_view`  (
                              `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                              `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会话ID',
                              `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户ID',
                              `page_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '页面URL',
                              `page_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '页面标题',
                              `referrer` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源页面',
                              `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户代理',
                              `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
                              `device_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型',
                              `browser` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '浏览器',
                              `os` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作系统',
                              `stay_time` bigint(20) NULL DEFAULT NULL COMMENT '停留时间(秒)',
                              `visit_time` datetime NOT NULL COMMENT '访问时间',
                              `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                              `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标记',
                              PRIMARY KEY (`id`) USING BTREE,
                              INDEX `idx_session_id`(`session_id`) USING BTREE,
                              INDEX `idx_user_id`(`user_id`) USING BTREE,
                              INDEX `idx_visit_time`(`visit_time`) USING BTREE,
                              INDEX `idx_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '页面访问记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of page_view
-- ----------------------------

-- ----------------------------
-- Table structure for product
-- ----------------------------
DROP TABLE IF EXISTS `product`;
CREATE TABLE `product`  (
                            `id` bigint(20) NOT NULL AUTO_INCREMENT,
                            `product_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品类型: master_service-大师服务, vip_plan-VIP套餐, course-课程, virtual-虚拟商品',
                            `product_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '商品编码(唯一标识，可用于业务逻辑)',
                            `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
                            `subtitle` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '副标题/简短描述',
                            `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '详细描述',
                            `icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '图标(emoji或图片URL)',
                            `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封面图片',
                            `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品图片列表(JSON数组)',
                            `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '现价(分转元)',
                            `original_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '原价(划线价)',
                            `cost_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '成本价',
                            `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'CNY' COMMENT '货币类型',
                            `stock` int(11) NULL DEFAULT -1 COMMENT '库存: -1无限, 0售罄, >0有限',
                            `sales_count` int(11) NULL DEFAULT 0 COMMENT '销量(冗余)',
                            `limit_per_user` int(11) NULL DEFAULT 0 COMMENT '每人限购: 0不限',
                            `valid_days` int(11) NULL DEFAULT 0 COMMENT '有效天数: 0永久',
                            `valid_start` datetime NULL DEFAULT NULL COMMENT '生效开始时间',
                            `valid_end` datetime NULL DEFAULT NULL COMMENT '生效结束时间',
                            `tag` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '角标: hot-热门, new-新品, recommend-推荐, limited-限时',
                            `group_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '分组编码(用于前端展示分组)',
                            `category_id` bigint(20) NULL DEFAULT 0 COMMENT '关联分类ID',
                            `extra` json NULL COMMENT '扩展配置(JSON): 如VIP权益、服务内容等',
                            `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序(越小越前)',
                            `is_recommend` tinyint(4) NULL DEFAULT 0 COMMENT '是否推荐: 0-否 1-是',
                            `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-下架 1-上架 2-预售',
                            `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建人',
                            `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '修改人',
                            `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                            `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                            PRIMARY KEY (`id`) USING BTREE,
                            UNIQUE INDEX `uk_product_code`(`product_code`) USING BTREE,
                            INDEX `idx_product_type`(`product_type`) USING BTREE,
                            INDEX `idx_group_code`(`group_code`) USING BTREE,
                            INDEX `idx_status`(`status`) USING BTREE,
                            INDEX `idx_sort`(`sort_order`) USING BTREE,
                            INDEX `idx_type_status`(`product_type`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '通用商品/服务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product
-- ----------------------------

-- ----------------------------
-- Table structure for site_stats
-- ----------------------------
DROP TABLE IF EXISTS `site_stats`;
CREATE TABLE `site_stats`  (
                               `id` int(11) NOT NULL DEFAULT 1,
                               `base_total_count` bigint(20) NULL DEFAULT 128650 COMMENT '总测算基数',
                               `base_today_count` int(11) NULL DEFAULT 1280 COMMENT '今日测算基数',
                               `base_online_count` int(11) NULL DEFAULT 38 COMMENT '在线人数基数',
                               `real_total_count` bigint(20) NULL DEFAULT 0 COMMENT '真实总测算次数',
                               `real_today_count` int(11) NULL DEFAULT 0 COMMENT '真实今日测算次数',
                               `real_online_count` int(11) NULL DEFAULT 0 COMMENT '真实在线人数',
                               `today_date` date NULL DEFAULT NULL COMMENT '当前日期',
                               `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '站点统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_stats
-- ----------------------------

-- ----------------------------
-- Table structure for sys_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config`  (
                               `id` bigint(20) NOT NULL AUTO_INCREMENT,
                               `config_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'system' COMMENT '配置分组: system-系统, payment-支付, master-大师服务, site-站点, seo-SEO',
                               `config_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置键',
                               `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置值',
                               `config_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'string' COMMENT '值类型: string, number, boolean, json, text, image',
                               `config_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '配置名称(中文)',
                               `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '配置说明',
                               `default_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '默认值',
                               `options` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可选值(JSON数组，用于下拉选择)',
                               `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                               `is_public` tinyint(4) NULL DEFAULT 0 COMMENT '是否公开(前端可读): 0-否 1-是',
                               `is_system` tinyint(4) NULL DEFAULT 0 COMMENT '是否系统配置(不可删除): 0-否 1-是',
                               `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-禁用 1-启用',
                               `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                               `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE INDEX `uk_group_key`(`config_group`, `config_key`) USING BTREE,
                               INDEX `idx_group`(`config_group`) USING BTREE,
                               INDEX `idx_public`(`is_public`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '通用配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_config
-- ----------------------------

-- ----------------------------
-- Table structure for t_chat_group
-- ----------------------------
DROP TABLE IF EXISTS `t_chat_group`;
CREATE TABLE `t_chat_group`  (
                                 `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '聊天组ID',
                                 `user_id` bigint(20) NOT NULL COMMENT '用户ID',
                                 `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题',
                                 `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型',
                                 `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                 `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                 `deleted` int(11) NULL DEFAULT 0 COMMENT '是否删除',
                                 PRIMARY KEY (`id`) USING BTREE,
                                 INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '聊天组表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_chat_group
-- ----------------------------

-- ----------------------------
-- Table structure for t_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `t_chat_message`;
CREATE TABLE `t_chat_message`  (
                                   `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '消息ID',
                                   `group_id` bigint(20) NOT NULL COMMENT '聊天组ID',
                                   `user_id` bigint(20) NOT NULL COMMENT '用户ID',
                                   `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色(user/assistant)',
                                   `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
                                   `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                   `deleted` int(11) NULL DEFAULT 0 COMMENT '是否删除',
                                   `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'gpt' COMMENT '消息类型',
                                   `sub_module` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子模块类型',
                                   `base64_type` int(11) NULL DEFAULT 0 COMMENT '内容类型',
                                   `base64_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'base64内容',
                                   `gen_by_gpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '语音转文字内容',
                                   PRIMARY KEY (`id`) USING BTREE,
                                   INDEX `idx_group_id`(`group_id`) USING BTREE,
                                   INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 101 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '聊天消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_chat_message
-- ----------------------------

-- ----------------------------
-- Table structure for t_feedback
-- ----------------------------
DROP TABLE IF EXISTS `t_feedback`;
CREATE TABLE `t_feedback`  (
                               `id` bigint(20) NOT NULL AUTO_INCREMENT,
                               `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID(可为空，支持匿名)',
                               `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '昵称',
                               `contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系方式',
                               `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '留言内容',
                               `images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片URL(JSON数组)',
                               `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'feedback' COMMENT '类型(feedback反馈/suggestion建议/bug问题)',
                               `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态(0待处理/1已处理/2已回复)',
                               `reply` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回复内容',
                               `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间',
                               `reply_by` bigint(20) NULL DEFAULT NULL COMMENT '回复人ID',
                               `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                               `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               `deleted` tinyint(4) NULL DEFAULT 0,
                               PRIMARY KEY (`id`) USING BTREE,
                               INDEX `idx_user_id`(`user_id`) USING BTREE,
                               INDEX `idx_status`(`status`) USING BTREE,
                               INDEX `idx_type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户留言表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_feedback
-- ----------------------------

-- ----------------------------
-- Table structure for t_order
-- ----------------------------
DROP TABLE IF EXISTS `t_order`;
CREATE TABLE `t_order`  (
                            `id` bigint(20) NOT NULL AUTO_INCREMENT,
                            `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
                            `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
                            `plan_id` bigint(20) NOT NULL COMMENT '套餐ID',
                            `plan_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '套餐名称',
                            `amount` decimal(10, 2) NOT NULL COMMENT '支付金额',
                            `pay_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付方式(wechat/alipay)',
                            `pay_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付类型(wechat/alipay)',
                            `pay_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付模式(qrcode/official)',
                            `trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方交易号',
                            `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
                            `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
                            `confirm_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人(admin/system)',
                            `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态(0待支付/1已支付/2已取消/3已退款)',
                            `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
                            `user_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户备注(如转账备注)',
                            `admin_remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '管理员备注',
                            `complete_time` datetime NULL DEFAULT NULL,
                            `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                            `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                            `deleted` tinyint(4) NULL DEFAULT 0,
                            PRIMARY KEY (`id`) USING BTREE,
                            UNIQUE INDEX `order_no`(`order_no`) USING BTREE,
                            INDEX `idx_user_id`(`user_id`) USING BTREE,
                            INDEX `idx_order_no`(`order_no`) USING BTREE,
                            INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_order
-- ----------------------------

-- ----------------------------
-- Table structure for t_payment_config
-- ----------------------------
DROP TABLE IF EXISTS `t_payment_config`;
CREATE TABLE `t_payment_config`  (
                                     `id` bigint(20) NOT NULL AUTO_INCREMENT,
                                     `config_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置键',
                                     `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置值',
                                     `config_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'string' COMMENT '配置类型(string/json/boolean)',
                                     `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置说明',
                                     `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                                     `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                     PRIMARY KEY (`id`) USING BTREE,
                                     UNIQUE INDEX `config_key`(`config_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_payment_config
-- ----------------------------

-- ----------------------------
-- Table structure for t_user
-- ----------------------------
DROP TABLE IF EXISTS `t_user`;
CREATE TABLE `t_user`  (
                           `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '用户ID',
                           `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
                           `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
                           `wechat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信号',
                           `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '密码',
                           `wallet_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '钱包地址',
                           `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '昵称',
                           `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像',
                           `vip_level` int(11) NULL DEFAULT 0 COMMENT '会员等级(0普通/1普通会员/2黄金/3钻石)',
                           `vip_expire_time` datetime NULL DEFAULT NULL COMMENT 'VIP过期时间',
                           `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                           `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                           `deleted` int(11) NULL DEFAULT 0 COMMENT '是否删除',
                           `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'user' COMMENT '用户角色: user-普通用户, admin-管理员',
                           PRIMARY KEY (`id`) USING BTREE,
                           UNIQUE INDEX `uk_email`(`email`) USING BTREE,
                           UNIQUE INDEX `uk_wallet`(`wallet_address`) USING BTREE,
                           INDEX `idx_user_phone`(`phone`) USING BTREE,
                           INDEX `idx_user_wechat`(`wechat`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_user
-- ----------------------------

-- ----------------------------
-- Table structure for t_vip_benefit
-- ----------------------------
DROP TABLE IF EXISTS `t_vip_benefit`;
CREATE TABLE `t_vip_benefit`  (
                                  `id` bigint(20) NOT NULL AUTO_INCREMENT,
                                  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '权益名称',
                                  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '权益编码',
                                  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权益描述',
                                  `icon` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图标URL',
                                  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                                  `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态(0禁用/1启用)',
                                  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                                  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                  `deleted` tinyint(4) NULL DEFAULT 0,
                                  PRIMARY KEY (`id`) USING BTREE,
                                  UNIQUE INDEX `code`(`code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员权益表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_vip_benefit
-- ----------------------------

-- ----------------------------
-- Table structure for t_vip_level_benefit
-- ----------------------------
DROP TABLE IF EXISTS `t_vip_level_benefit`;
CREATE TABLE `t_vip_level_benefit`  (
                                        `id` bigint(20) NOT NULL AUTO_INCREMENT,
                                        `vip_level` int(11) NOT NULL COMMENT '会员等级(0普通用户/1普通会员/2黄金会员/3钻石会员)',
                                        `benefit_id` bigint(20) NOT NULL COMMENT '权益ID',
                                        `benefit_value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权益值(如部分/全部/具体数量)',
                                        `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                                        PRIMARY KEY (`id`) USING BTREE,
                                        UNIQUE INDEX `uk_level_benefit`(`vip_level`, `benefit_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员等级权益关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_vip_level_benefit
-- ----------------------------

-- ----------------------------
-- Table structure for t_vip_plan
-- ----------------------------
DROP TABLE IF EXISTS `t_vip_plan`;
CREATE TABLE `t_vip_plan`  (
                               `id` bigint(20) NOT NULL AUTO_INCREMENT,
                               `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '套餐名称',
                               `code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '套餐编码(3month/1year/5year等)',
                               `duration_days` int(11) NOT NULL COMMENT '有效天数',
                               `original_price` decimal(10, 2) NOT NULL COMMENT '原价(元)',
                               `current_price` decimal(10, 2) NOT NULL COMMENT '现价(元)',
                               `discount` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '折扣标签(如5折)',
                               `badge` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '角标(如推荐/热销)',
                               `vip_level` int(11) NOT NULL DEFAULT 1 COMMENT '会员等级(1普通/2黄金/3钻石)',
                               `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                               `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态(0禁用/1启用)',
                               `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
                               `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               `deleted` tinyint(4) NULL DEFAULT 0,
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE INDEX `code`(`code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员套餐表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_vip_plan
-- ----------------------------

-- ----------------------------
-- Table structure for tag
-- ----------------------------
DROP TABLE IF EXISTS `tag`;
CREATE TABLE `tag`  (
                        `id` bigint(20) NOT NULL AUTO_INCREMENT,
                        `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签名',
                        `article_count` int(11) NULL DEFAULT 0 COMMENT '文章数量(冗余)',
                        `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                        `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-禁用 1-启用',
                        `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建人',
                        `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '修改人',
                        `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                        `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
                        PRIMARY KEY (`id`) USING BTREE,
                        UNIQUE INDEX `uk_name`(`name`) USING BTREE,
                        INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章标签' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tag
-- ----------------------------

-- ----------------------------
-- Table structure for tool_stats
-- ----------------------------
DROP TABLE IF EXISTS `tool_stats`;
CREATE TABLE `tool_stats`  (
                               `tool_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
                               `tool_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工具名称',
                               `tool_icon` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工具图标',
                               `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类',
                               `base_total` int(11) NULL DEFAULT 0 COMMENT '总使用基数',
                               `base_today` int(11) NULL DEFAULT 0 COMMENT '今日使用基数',
                               `real_total` bigint(20) NULL DEFAULT 0 COMMENT '真实总使用次数',
                               `real_today` int(11) NULL DEFAULT 0 COMMENT '真实今日使用次数',
                               `today_date` date NULL DEFAULT NULL COMMENT '当前日期',
                               `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
                               `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               PRIMARY KEY (`tool_id`) USING BTREE,
                               INDEX `idx_category`(`category`) USING BTREE,
                               INDEX `idx_sort`(`sort_order`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工具统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tool_stats
-- ----------------------------

-- ----------------------------
-- Table structure for user_behavior
-- ----------------------------
DROP TABLE IF EXISTS `user_behavior`;
CREATE TABLE `user_behavior`  (
                                  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户ID',
                                  `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会话ID',
                                  `event_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型',
                                  `event_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件名称',
                                  `page_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '页面URL',
                                  `target_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标URL',
                                  `properties` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事件属性(JSON)',
                                  `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
                                  `device_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型',
                                  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户代理',
                                  `duration` bigint(20) NULL DEFAULT NULL COMMENT '持续时间(毫秒)',
                                  `success` tinyint(1) NULL DEFAULT 1 COMMENT '是否成功',
                                  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标记',
                                  PRIMARY KEY (`id`) USING BTREE,
                                  INDEX `idx_user_id`(`user_id`) USING BTREE,
                                  INDEX `idx_session_id`(`session_id`) USING BTREE,
                                  INDEX `idx_event_type`(`event_type`) USING BTREE,
                                  INDEX `idx_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户行为记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_behavior
-- ----------------------------

